Record stpH (mem : word -> option byte) (sp endp : word) (can : Z) : Prop := STPH {
  Psp16  : bv_unsigned sp mod 16 = 0;
  PspLo  : 0x200000 <= bv_unsigned sp;
  PspHi  : bv_unsigned sp <= 0x7fffffffffff;
  PeLo   : 0x200000 <= bv_unsigned endp;
  PeHi   : bv_unsigned endp <= 0x7fffffffffff;
  Pstk   : stk_ok RSEGS mem sp ST_FR;
  Pend   : forall d m, 0 <= d -> d + Z.of_nat m <= 8 -> store_ok RSEGS mem (Z_to_bv 64 (bv_unsigned endp + d)) m = true;
  Pdisj1 : bv_unsigned sp <= bv_unsigned endp \/ bv_unsigned endp + 8 <= bv_unsigned sp - ST_FR;
  Pimg   : forall i, 0x10000 <= i < 0x7e000 -> mem (Z_to_bv 64 i) = None;
  Pgot   : rdn RSEGS mem (Z_to_bv 64 0x83b30) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0xb69b0));
  Pcan   : rdn RSEGS mem (Z_to_bv 64 0xb69b0) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 can));
  Pcan64 : 0 <= can < 2 ^ 64 }.

Definition stp_vals (regs : bvmap 5 word) (sp endp : word) (can : Z) : list word :=
  [sp; endp; Z_to_bv 64 can] ++ junk_vals regs.
Definition stpE (regs : bvmap 5 word) (sp endp : word) (can : Z) : env :=
  Env (vals_ev (stp_vals regs sp endp can)) (blobs_ev []).

Definition stp_sr : list expr :=
  Eval cbv in (map (fun i => match i with
     | 0 => ELit 0 | 2 => EVar 0 | 10 => ELit ST_ONE | 11 => EVar 1 | 12 => ELit 0
     | _ => EVar (3 + i) end)%nat (seq 0 32)).

Definition stp_kn : list kentry :=
  [KAlign (EVar 0) 16; KRange (EVar 0) 0x200000 0x7fffffffffff;
   KRange (EVar 1) 0x200000 0x7fffffffffff;
   KWr (SA (EVar 0) (-368)) 368;
   KWr (SA (EVar 1) 0) 8;
   KDisj (SA (EVar 0) (-368)) 368 (SA (EVar 1) 0) 8;
   KImg 0x10000 0x7e000;
   KWord (SA (ELit 0) 0x83b30) 8 (ELit 0xb69b0);
   KWord (SA (ELit 0) 0xb69b0) 8 (EVar 2)].

